using System;using System.IO;using System.Linq;using System.Text;using System.Threading;using System.Windows.Forms;using System.Windows.Media.Media3D;
namespace GearLab {public static class Gripper671Tests {
 static int checks;static void Check(bool b,string m){checks++;if(!b)throw new Exception(m);}static void Wait(Func<bool> f){var w=System.Diagnostics.Stopwatch.StartNew();while(!f()&&w.Elapsed.TotalSeconds<100){Application.DoEvents();Thread.Sleep(15);}Check(f(),"scene ready");}static void Call(object target,string name){target.GetType().GetMethod(name,System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(target,new object[0]);}
 public static int Run(string folder){Directory.CreateDirectory(folder);var old=AppSettings.Current;try{AppSettings.Current=new AppSettings{AutoSave=false};var d=ReferenceRobot67.Cached();using(var r=new RobotDesignerForm())using(var shell=new WorkspaceShell(r)){r.SetDocument(d);shell.Show();Wait(()=>r.Scene.Ready&&r.WebScene.Ready);var until=DateTime.UtcNow.AddSeconds(1);Wait(()=>DateTime.UtcNow>until);r.OpenJointControllers();r.JogJoint(d.Joints[1].Id,5);var positions=d.Joints.Select(j=>j.Position).ToArray();var build=r.Build;var nodes=r.Scene.Nodes.ToArray();var geometry=nodes.Select(n=>n.Frozen).ToArray();int clears=r.WebScene.ClearCount,uploads=r.WebScene.PartUploadCount;var fp=d.Joints.Select(j=>j.GeneratedBody.Fingerprint).ToArray();double yaw=r.Scene.Camera.Yaw,width=r.Scene.Camera.Width;var target=r.Scene.Camera.Target;var last=d.Joints.Last();string id=last.Id+"_tool_jaw_1";var initialPartPlacement=build.Entries[id].Part.Placement;
 foreach(double opening in new[]{2.0,26,0,40,12,2,26,2}){var watch=System.Diagnostics.Stopwatch.StartNew();r.SetGripperOpening(opening);Check(ReferenceEquals(build,r.Build),"gripper reuses robot assembly");Check(nodes.SequenceEqual(r.Scene.Nodes),"gripper reuses scene nodes");Check(geometry.SequenceEqual(r.Scene.Nodes.Select(n=>n.Frozen)),"gripper reuses frozen triangle geometry");Check(r.WebScene.ClearCount==clears&&r.WebScene.PartUploadCount==uploads,"no WebGL clear or mesh upload");Check(d.Joints.Select(j=>j.Position).SequenceEqual(positions),"arm pose is preserved");Check(d.Joints.Select(j=>j.GeneratedBody.Fingerprint).SequenceEqual(fp),"native CAD caches remain current");Check(r.Scene.Camera.Yaw==yaw&&r.Scene.Camera.Width==width&&r.Scene.Camera.Target==target,"camera is preserved");var left=build.Entries[last.Id+"_tool_jaw_-1"];var right=build.Entries[id];Check(Math.Abs(right.Shape.X-left.Shape.X-opening-4)<1e-7,"jaw metadata follows opening");var expected=right.Local;expected.Translate(right.GripperSlide*((opening-right.GripperReferenceOpening)/2));expected=expected*build.Current[last.Id].Output;Check(build.Pose(id,0,false)==expected,"jaw transform follows local tool axis");File.AppendAllText(Path.Combine(folder,"gripper671-timing.txt"),opening+" mm: "+watch.Elapsed.TotalMilliseconds.ToString("F1")+" ms\r\n");}
 Call(r,"Undo");Check(d.GripperOpening==26&&ReferenceEquals(build,r.Build),"undo gripper without rebuild");Call(r,"Redo");Check(d.GripperOpening==2&&ReferenceEquals(build,r.Build),"redo gripper without rebuild");Check(r.WebScene.ClearCount==clears&&r.WebScene.PartUploadCount==uploads,"undo and redo reuse WebGL meshes");var exported=build.ForExport(false,id).Parts.Single();Check(exported.Placement==build.Pose(id,0,false),"export snapshots the current gripper pose");Check(!ReferenceEquals(exported,build.Entries[id].Part)&&build.Entries[id].Part.Placement==initialPartPlacement,"export does not move the live scene");var restored=RobotCad.Build(RobotDocument.Parse(d.Serialize()));var a=PrintExport.Mesh(exported).Points.Select(exported.Placement.Transform).ToArray();var rp=restored.Entries[id].Part;var b=PrintExport.Mesh(rp).Points.Select(restored.Pose(id,0,false).Transform).ToArray();Check((a.Aggregate(new Vector3D(),(s,p)=>s+RobotMath.Vector(p))/a.Length-b.Aggregate(new Vector3D(),(s,p)=>s+RobotMath.Vector(p))/b.Length).Length<1e-6,"saved/reopened gripper matches live export");var shot=r.WebScene.SavePreview(Path.Combine(folder,"gripper671-closed.png"));Wait(()=>shot.IsCompleted);shot.GetAwaiter().GetResult();shell.ApproveTestClose();shell.Close();}File.WriteAllText(Path.Combine(folder,"gripper671-results.txt"),"PASS "+checks+" assertions: live gripper, no mesh rebuild/upload, preserved camera and arm pose, undo/redo and current export.",Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"gripper671-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{AppSettings.Current=old;}}
}}
